import Link from 'next/link';
import { forbidden } from 'next/navigation';

import { verifyAdmin } from '../lib/auth';

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <main
      style={{
        minHeight: '100vh',
        padding: '48px 24px',
        background:
          'linear-gradient(180deg, #f7f4ef 0%, #f0ede6 50%, #e6e2db 100%)',
        color: '#1f1b16'
      }}
    >
      <section
        style={{
          maxWidth: '680px',
          margin: '0 auto',
          padding: '32px',
          borderRadius: '20px',
          background: '#ffffff',
          boxShadow: '0 18px 45px rgba(31, 27, 22, 0.12)'
        }}
      >
        <p style={{ fontSize: '12px', letterSpacing: '0.18em' }}>ADMIN AREA</p>
        <h1 style={{ fontSize: '32px', margin: '12px 0' }}>Dashboard</h1>
        <p style={{ fontSize: '18px', lineHeight: 1.6 }}>
          Welcome back, {session?.name ?? 'Admin'}. You have access to privileged
          controls and system insights.
        </p>
        <div style={{ marginTop: '28px' }}>
          <Link href="/">Return to home</Link>
        </div>
      </section>
    </main>
  );
}

